def pin_existing_agent_hosts(apps, schema_editor):
    """存量已绑 agent 的主机置 mode=agent，保持改动前的执行通道不变。

    不做这步，这些主机会退到 auto，而此时还没有任何路由规则 → 静默改走直连，
    NAT 内网主机下一次执行才会以 SSH 超时的形式暴露。
    """
    Server = apps.get_model('asset_mgr', 'Server')
    Server.objects.filter(agent__isnull=False).update(channel_mode='agent')


def unpin(apps, schema_editor):
    """回滚到「有 agent 即经 agent」的旧语义：非 agent 模式的主机清空 agent。

    靠规则（mode=auto）路由的主机回滚后一律变直连——旧模型没有承载规则的字段，
    回滚前需要人工把这些主机改回逐台绑定。
    """
    Server = apps.get_model('asset_mgr', 'Server')
    Server.objects.exclude(channel_mode='agent').update(agent=None)


